
import pandas as pd
from datetime import datetime


def generate_maintenance_report(
    input_csv="extracted_features.csv",
    report_output="maintenance_report.txt"
):
    try:
        df = pd.read_csv(input_csv)

    except FileNotFoundError:
        print(f"Error: Input file '{input_csv}' was not found.")
        return

    except Exception as error:
        print(f"Error reading dataset: {error}")
        return

    # Match the actual column generated by realtime_consumer.py.
    if "anomaly" in df.columns:
        anomaly_column = "anomaly"
    elif "anomaly_flag" in df.columns:
        anomaly_column = "anomaly_flag"
    else:
        print("Error: No anomaly column found in the input CSV.")
        return

    df[anomaly_column] = pd.to_numeric(
        df[anomaly_column],
        errors="coerce"
    ).fillna(0).astype(int)

    critical_events = df[df[anomaly_column] == 1]

    report_content = [
        "=" * 55,
        "       AUTOMATED MAINTENANCE INCIDENT REPORT",
        f"Generated On: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}",
        "=" * 55,
        "",
        f"Total Sensor Windows Processed: {len(df)}",
        f"Total Anomalous Events Flagged: {len(critical_events)}",
        ""
    ]

    if not critical_events.empty:
        report_content.append("--- AT-RISK MACHINERY DETAILS ---")

        for _, row in critical_events.iterrows():
            window_id = row.get("window", "N/A")
            peak_amp = row.get("peak_amplitude", "N/A")
            frequency = row.get("dominant_frequency", "N/A")
            alert_status = row.get("alert_status", "N/A")

            report_content.append(
                f"[ANOMALY] Window #{window_id} | "
                f"Peak Amplitude: {peak_amp} | "
                f"Frequency: {frequency} Hz | "
                f"Alert Status: {alert_status}"
            )

    else:
        report_content.append(
            "[STATUS: OK] No anomalous windows were flagged."
        )

    report_content.extend([
        "",
        "Note: Anomaly flags indicate potential abnormal behaviour,",
        "not confirmed mechanical failures.",
        "=" * 55
    ])

    with open(report_output, "w", encoding="utf-8") as file:
        file.write("\n".join(report_content))

    print(f"Maintenance report generated: {report_output}")
    print(f"Windows processed: {len(df)}")
    print(f"Anomalous windows: {len(critical_events)}")


if __name__ == "__main__":
    generate_maintenance_report()
